INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-02', 'Exposed deck SOLAS II-1- Part B', 'Checking for absence of corrosion, deformation, fracture and weld corrosion, with particular attention to: fracture at the hatch corner and at the connections of the hatch end beams and top side tanks.', 'GOOD', 'Checked and verified.', '', NULL);
INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-03', 'Cargo tanks/holds SOLAS II-/1 Part B', 'Checking of the condition of side shell frames and transverse bulkheads, tank top plating for absence of corrosion, deformation, fracture, weld corrosion and detachment of frames and brackets, with particular attention to corrosion, fracture and detachment of side shell frames on their webs; corrosion, fracture and detachment at the toes of the upper and lower brackets of the side frames; fracture at the weld connections of the corrugated bulkhead to the stool; fracture at the other weld connections of transverse bulkheads or stools structure to boundaries; corrosion at the mid-height and bottom of the transverse bulkheads; fracture at the transition regions with fore bulkhead of engine room and collision bulkhead due to discontinuities of the longitudinal structure.', 'GOOD', 'Checked and verified.', '', NULL);
INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-04', 'Ballast tanks SOLAS II-1 Part B', 'Checking of the coating condition with a general inspection: Further checking if the coating is in fair or poor condition of the ballast tanks condition for absence of corrosion, deformation, fracture with particular attention to corrosion of the internal structure of the top side tanks and inlets or outlets sea water valves due to the heat of upper deck and moisture in the tank; fracture at the corners of transverse webs in top side tank, hopper tank and at the transverse brackets where there is no transverse web; fracture in way of the connections of longitudinals to transverse webs, i.e.; at the cut out of the transverse web in top side tank and hopper tank; fracture in way of the knuckle between the inner bottom and hopper tank sloping plating; fracture in the double bottom in way of the connections of the longitudinals to floors, i.e. at the cut out of floors and at the discontinuities of the longitudinals; fracture at the edge of the un-reinforced openings and manholes; fracture at the connections of the deck longitudinals to the bulkheads.', 'GOOD', 'Checked and verified.', '', NULL);
INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-05', 'Aft/Forepeak Tank', 'Checking of the condition for absence of corrosion, deformation, fracture, weld corrosion and detachment of frames, with particular attention to corrosion at the top of fore/aft peak; fracture of the side shell and damage of the internal structure in the fore peak due to collision; fracture of the internal structure of the aft peak due to propeller vibrations; inspection of the coating or anodes if applicable.', 'GOOD', 'Checked and verified.', '', NULL);
INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-06', 'Engine Room', 'Checking of the condition for absence of corrosion, deformation and fracture, with particular attention to corrosion of the inner bottom plating; corrosion and fracture at the web connections of the top bottom and of side shell plating to the fore/aft bulkheads; Inspection of M/E cofferdam.', 'GOOD', 'Checked and verified.', '', NULL);
INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-07', 'Other compartments Bos’n store, deck stores. SOLAS II-1 Part B', 'Checking of the condition fro absence of corrosion, deformation and fracture with particular attention to corrosion at the bottom of f’cle spaces and bosun store; corrosion at the joint of the top of fore peak and the aft wall of f’cle; corrosion and deformation at side shell plantings of the f’cle due to rough seas or contact with other objects such as quay, buoy or other vessels.', 'GOOD', 'Checked and verified.', '', NULL);
INSERT INTO hull_structure (vessel_id, company_id, user_id, s_no, rule_ref, requirements, ans, comments, image, report_id) VALUES ('b4871f10-60cc-4a4a-a49b-bb22b290f206', 'c1348bc9-16cd-4d5f-ad32-bf752c69e223', '2b42a774-4c2e-4bc7-a0a4-6b595ed6cee2', 'HUL-STR-08', 'Superstructure end bulkhead', 'Checking for absence of corrosion, deformation and fractures, with particular attention to lower part of superstructures and deck house walls', 'GOOD', 'Checked and verified.', '', NULL);
